public static FMTotalsEngine construct()
{
    FMTotalsEngine engine = new FMTotalsEngine();
    return engine;
}

/// <summary>
/// Calculates the totals for the given rental. Does not persists result in DB, only updates valued in parameter buffer
/// </summary>
/// <param name = "_rental"></param>
public void calculateRentalVehicleRate(FMRental _rental)
{        
    _rental.VehicleRateTotal = _rental.rentalLengthInDays() * _rental.VehicleRatePerDay;
}

/// <summary>
/// </summary>
/// <param name = "rental"></param>
/// <returns>The discounted vehicle rate</returns>
private real calculateDiscountedVehicleRateForPeriod(FMRental _rental)
{
    real discountedVehicleRate;
    int rentalPeriodInDays = _rental.rentalLengthInDays();

    discountedVehicleRate = (rentalPeriodInDays div 7) * _rental.VehicleRatePerWeek + (rentalPeriodInDays mod 7) * _rental.VehicleRatePerDay;

    return discountedVehicleRate;
}

public FMChargesTotal chargesTotals(FMRental _rental)
{
    FMRentalCharge  rentalCharge;

    if (_rental.RentalId)
    {
        select firstonly sum(ExtendedAmount) from rentalCharge
            where rentalCharge.RentalId == _rental.RentalId;
    }

    return rentalCharge.ExtendedAmount > 0 ? rentalCharge.ExtendedAmount : 0;
}

public FMRentalTotal totals(FMRental _rental)
{
    real discountedVehicleRate = this.calculateDiscountedVehicleRateForPeriod(_rental);
    FMRentalTotal result = discountedVehicleRate + this.chargesTotals(_rental);

    return result > 0 ? result : 0;
}

public FMSavingsTotal savings(FMRental _rental)
{
    real discountedVehicleRate = this.calculateDiscountedVehicleRateForPeriod(_rental);
    return discountedVehicleRate - _rental.VehicleRateTotal;
}
